window.ScripturaLexicons.BDAG_PART_0364 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0364-01\" data-source=\"BDAG\" data-search=\"Τρωγύλλιον, ου, τό nome próprio neutro Trogílio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Τρωγύλλιον, ου, τό</td><td>nome próprio neutro</td><td>Trogílio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0364-02\" data-source=\"BDAG\" data-search=\"τρώγω verbo morder; mastigar; comer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τρώγω</td><td>verbo</td><td>morder; mastigar; comer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0364-03\" data-source=\"BDAG\" data-search=\"τυγχάνω verbo encontrar; alcançar; acontecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τυγχάνω</td><td>verbo</td><td>encontrar; alcançar; acontecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0364-04\" data-source=\"BDAG\" data-search=\"τυμπανίζω verbo torturar; atormentar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τυμπανίζω</td><td>verbo</td><td>torturar; atormentar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0364-05\" data-source=\"BDAG\" data-search=\"τυπικῶς advérbio como exemplo; como advertência BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τυπικῶς</td><td>advérbio</td><td>como exemplo; como advertência</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0364-06\" data-source=\"BDAG\" data-search=\"τύπος, ου, ὁ substantivo masculino marca; imagem; padrão; tipo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τύπος, ου, ὁ</td><td>substantivo masculino</td><td>marca; imagem; padrão; tipo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0364-07\" data-source=\"BDAG\" data-search=\"τύπτω verbo golpear; bater; ferir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τύπτω</td><td>verbo</td><td>golpear; bater; ferir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0364-08\" data-source=\"BDAG\" data-search=\"τυραννίς, ίδος, ἡ substantivo feminino tirania; governo despótico BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τυραννίς, ίδος, ἡ</td><td>substantivo feminino</td><td>tirania; governo despótico</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0364-09\" data-source=\"BDAG\" data-search=\"τύραννος, ου, ὁ substantivo masculino déspota; tirano BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τύραννος, ου, ὁ</td><td>substantivo masculino</td><td>déspota; tirano</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0364-10\" data-source=\"BDAG\" data-search=\"Τύραννος, ου, ὁ nome próprio masculino Tirano BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Τύραννος, ου, ὁ</td><td>nome próprio masculino</td><td>Tirano</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0364-11\" data-source=\"BDAG\" data-search=\"τυρβάζω verbo inquietar-se; agitar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τυρβάζω</td><td>verbo</td><td>inquietar-se; agitar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0364-12\" data-source=\"BDAG\" data-search=\"Τύριος, ου, ὁ gentílico masculino tírio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Τύριος, ου, ὁ</td><td>gentílico masculino</td><td>tírio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0364-13\" data-source=\"BDAG\" data-search=\"Τύρος, ου, ἡ nome próprio feminino Tiro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Τύρος, ου, ἡ</td><td>nome próprio feminino</td><td>Tiro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0364-14\" data-source=\"BDAG\" data-search=\"τυφλός, ή, όν adjetivo cego BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τυφλός, ή, όν</td><td>adjetivo</td><td>cego</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0364-15\" data-source=\"BDAG\" data-search=\"τυφλόω verbo cegar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τυφλόω</td><td>verbo</td><td>cegar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0364-16\" data-source=\"BDAG\" data-search=\"τῦφος, ους, τό substantivo neutro ilusão; presunção; arrogância BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τῦφος, ους, τό</td><td>substantivo neutro</td><td>ilusão; presunção; arrogância</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0364-17\" data-source=\"BDAG\" data-search=\"τυφόω verbo ensoberbecer-se; tornar-se insensato BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τυφόω</td><td>verbo</td><td>ensoberbecer-se; tornar-se insensato</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0364-18\" data-source=\"BDAG\" data-search=\"τύφω verbo fumegar; bruxulear BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τύφω</td><td>verbo</td><td>fumegar; bruxulear</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0364-19\" data-source=\"BDAG\" data-search=\"τυφωνικός, ή, όν adjetivo semelhante a um turbilhão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τυφωνικός, ή, όν</td><td>adjetivo</td><td>semelhante a um turbilhão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0364-20\" data-source=\"BDAG\" data-search=\"τυχεῖν, τύχοι formas verbais remissão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τυχεῖν, τύχοι</td><td>formas verbais</td><td>remissão</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0364-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τρωγύλλιον, ου, τό</h1><div class=\"entry-meta\"><span>nome próprio neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Τρωγύλλιον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Strabo, Ptolem. et al., em grafias variantes; B-D-F §42, 3) Trogílio, promontório e cidade ao sul de Éfeso, na Ásia Menor. Segundo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:15</a> v.l. <span class=\"greek\">ἐν</span> <span class=\"greek\">Τρωγυλλίῳ</span> (D tem <span class=\"greek\">ἐν</span> <span class=\"greek\">Τρωγυλίᾳ</span>; outra v.l. <span class=\"greek\">ἐν</span> <span class=\"greek\">Τρωγυλίῳ</span>), Paulo permaneceu ali uma noite.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0364-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρώγω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τρώγω</span> (Hom. et al.; TestJob 12:2; SIG 1171, 9; PGM 7, 177; Sb 5730, 5. Não encontrado na LXX, EpArist, Philo ou Joseph. B-D-F §101 s.v. <span class=\"greek\">ἐσθίειν</span>; 169, 2; Rob. 351; JHaussleiter, Archiv für lat. Lexikographie 9, 1896, 300–302; GKilpatrick em: Studies and Documents 29, ’67, 153) morder ou mastigar alimento, comer (audivelmente), a respeito de animais (Hom. et al. ‘mastigar, mordiscar, mastigar ruidosamente’) B 10:3.—A respeito de seres humanos (Hdt. et al. e assim no grego moderno) <span class=\"greek\">τὶ</span> algo (Hdt. 1, 71, 3 <span class=\"greek\">σῦκα</span>; Aristoph., Equ. 1077) B 7:8. <span class=\"greek\">ὁ</span> <span class=\"greek\">τρώγων</span> <span class=\"greek\">μου</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἄρτον</span> como símbolo de íntima convivência (Polyb. 31, 23, 9 <span class=\"greek\">δύο</span> <span class=\"greek\">τρώγομεν</span> <span class=\"greek\">ἀδελφοί</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:18</a> (v. Ps 40:10 <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐσθίων</span> <span class=\"greek\">ἄρτους</span> <span class=\"greek\">μου</span>, que constitui a base desta passagem). Com gen. (Athen. 8, 334b <span class=\"greek\">τῶν</span> <span class=\"greek\">σύκων</span>) Hs 5, 3, 7. Abs. B 10:2. Com <span class=\"greek\">πίνειν</span> (Demosth. 19, 197; Plut., Mor. 613b; 716e) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:38</a>. João emprega-o para contrabalançar quaisquer tendências a ‘espiritualizar’ o conceito de tal maneira que nada de físico permaneça nele, naquilo que muitos consideram a linguagem da Ceia do Senhor <span class=\"greek\">ὁ</span> <span class=\"greek\">τρώγων</span> <span class=\"greek\">τοῦτον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἄρτον</span> 6:58. <span class=\"greek\">ὁ</span> <span class=\"greek\">τρώγων</span> <span class=\"greek\">με</span> v. 57. <span class=\"greek\">ὁ</span> <span class=\"greek\">τρώγων</span> <span class=\"greek\">μου</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σάρκα</span> (com <span class=\"greek\">πίνων</span> <span class=\"greek\">μου</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">αἷμα</span>) vv. 54, 56.—B. 327. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0364-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυγχάνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τυγχάνω</span> (Hom.+) imperf. <span class=\"greek\">ἐτύγχανον</span>; fut. <span class=\"greek\">τεύξομαι</span>; 2 aor. <span class=\"greek\">ἔτυχον</span>; 1 aor. méd. inf. <span class=\"greek\">τεύξασθαι</span> LXX. Perf. (em lugar do ático <span class=\"greek\">τετύχηκα</span>, v. Phryn. p. 395 Lob.) <span class=\"greek\">τέτευχα</span> (jôn. [Hdt. e Hippocr.; v. Kühner-Bl. II 556], depois Aristot. et al.; OGI 194, 31 [42 a.C.]; papiros [Mayser I/22 ’38, 151f]; LXX [Thackeray §24 p. 287]; EpArist 121; Nachmanson 160, 1; Crönert 279; Schmid I 86; IV 40 e 600) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:6</a> v.l. ou, como no texto, <span class=\"greek\">τέτυχα</span> (Diod S 12, 17, 99; Aesop, Fab. 363 H. [eliminado por correção]; Jos., Bell. 7, 130 [eliminado por correção]; EpArist 180 <span class=\"greek\">συντέτυχε</span>); v. B-D-F §101; W-S. §13, 2; Mlt-H. 262.</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> experimentar algum acontecimento, encontrar, alcançar, obter, achar, experimentar, com gen. de pessoa ou coisa que se encontra etc. (Hom. et al.; LXX; TestAbr A 19 p. 102, 9 [Stone p. 52]; GrBar 17:4; AssMos, apologistas) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:2</a>; 26:22; 27:3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:10</a> (Diod S 4, 48, 7 <span class=\"greek\">τετεύχασι</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σωτηρίας</span>. Com a v.l. <span class=\"greek\">σωτηρίαν</span> nos mss. FG cf. Solon 24, 2 D.2 <span class=\"greek\">τυγχ</span>. <span class=\"greek\">τι</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:6</a>; 11:35; 1 Cl 61:2; 2 Cl 15:5; Dg 2:1; 9:6; IEph 10:1; IMg 1:3; ISm 9:2; 11:3; IPol 4:3; Hm 10, 1, 5; Hs 9, 26, 4.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> revelar-se no resultado, acontecer, resultar, intr.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> acontecer de estar, encontrar-se (X., Hell. 4, 3, 3; Tob 5:13 AB; TestJob 36:5; ApcMos 9; Just., D. 3, 2; Ath., R. p. 78, 14) <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκὶ</span> <span class=\"greek\">τυγχάνειν</span> Dg 5:8; <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">γῆς</span> 10:7. <span class=\"greek\">ἀφέντες</span> <span class=\"greek\">ἡμιθανῆ</span> <span class=\"greek\">τυγχάνοντα</span> deixaram-no semimorto, como de fato estava <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:30</a> v.l.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> <span class=\"greek\">εἰ</span> <span class=\"greek\">τύχοι</span> como fórmula, se assim acontecer, talvez (Cleanthes, Fgm. 529 vArnim=Sext. Emp., Math. 9, 89; Dionys. Hal. 4, 19; Hero Alex. III p. 220, 13; Dio Chrys. 16 [33], 53; Philo [KReik, Der Opt. bei Polyb. u. Philo von Alex. 1907, 154]; Just., D. 27, 3; B-D-F §385, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.37\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:37</a> (cf. Plut., Fgm. 104, ed. Sanbach, ’67 <span class=\"greek\">πυροῦ</span> <span class=\"greek\">τυχὸν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">κριθῆς</span>=talvez de trigo ou cevada); Dg 2:3. Em <span class=\"greek\">τοσαῦτα</span> <span class=\"greek\">εἰ</span> <span class=\"greek\">τύχοι</span> <span class=\"greek\">γένη</span> <span class=\"greek\">φωνῶν</span> <span class=\"greek\">εἰσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:10</a>, <span class=\"greek\">εἰ</span> <span class=\"greek\">τύχ</span>. provavelmente se destina a restringir <span class=\"greek\">τοσαῦτα</span> (Heinrici: JWeiss) há provavelmente muitíssimas línguas diferentes (Goodsp.—Nicol. Dam.: 90 Fgm. 130, 110 Jac. <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἣν</span> <span class=\"greek\">τύχοι</span> <span class=\"greek\">πρόφασιν</span>=‘sob quem sabe que espécie de pretexto’).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓒ</span> <span class=\"greek\">τυχόν</span>, propriamente o acus. absoluto do neut. do partic. aor. (B-D-F §424; Rob. 490), se assim acontecer, talvez, se possível (X., An. 6, 1, 20; Ps.-Pla., Alcib. 2, 140a; 150c; Epict. 1, 11, 11; 2, 1, 1; 3, 21, 18 al.; carta [IV a.C.] em Dssm., LO 121 [LAE 151]; Just., D. 4, 7 <span class=\"greek\">τὸ</span> <span class=\"greek\">τυχόν</span>; SIG 1259, 8; SibOr 5, 236) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:13</a> D; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:15</a> D.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓓ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τυχών</span> o primeiro que por acaso se encontra no caminho (X., Pla. et al.; Philo, Op. M. 137), daí <span class=\"greek\">οὐχ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τυχών</span> não o comum ou ordinário (Fgm. Com. Att. III 442 Fgm. 178 Kock; Theophr., HP 8, 7, 2; <span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> 9 [a respeito de Moisés]. Numerosos outros exemplos da literatura em Wettstein sobre Ac 19:11. Inscrições da época ptolomaica: BCH 22, 1898 p. 89 <span class=\"greek\">θόρυβον</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τυχόντα</span> <span class=\"greek\">παρέχοντες</span>; SIG 528, 10 [221/219 a.C.] <span class=\"greek\">ἀρωστίαις</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">τυχούσαις</span>; BGU 36, 9; POxy 899, 14; 3 Macc 3:7; Jos., Ant. 2, 120; 6, 292) <span class=\"greek\">δυνάμεις</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">τυχούσας</span> milagres extraordinários Ac 19:11. Cf. 28:2; 1 Cl 14:2.—B. 658. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0364-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυμπανίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τυμπανίζω</span> (<span class=\"greek\">τύμπανον</span> ‘tambor, tamborim’, p. ex. Eur., Bacch. 156, Herac. 891) 1 aor. partic. <span class=\"greek\">τυμπανίσας</span> (ViAm 1 [p. 81, 11 Sch.]), pass. <span class=\"greek\">ἐτυμπανίσθην</span> ‘torturar com um instrumento chamado <span class=\"greek\">τύμπανον</span>’ (assim Aristoph., Plut. 476 et al.; 2 Macc 6:19, 28. V. L-S-J-M s.v. <span class=\"greek\">τύμπανον</span> II 1 e <span class=\"greek\">ἀποτυμπανίζω</span>.—AKeramopoulos, <span class=\"greek\">Ο</span> <span class=\"greek\">Αποτυμπανισμος</span> 1923), depois atormentar, torturar em geral (Aristot., Rhet. 2, 5; Plut., Mor. 60a; Lucian, Jupp. Tr. 19. O composto <span class=\"greek\">ἀποτυμπ</span>. no mesmo sentido Plut., Dio 28, 2; UPZ 119, 37 [156 a.C.]; 3 Macc 3:27; Jos., C. Ap. 1, 148) pass. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.35\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:35</a>.—EOwen, JTS 30, 1929, 259–66.—DELG s.v. <span class=\"greek\">τύμπανον</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0364-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυπικῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τυπικῶς</span> (<span class=\"greek\">τύπος</span>; Rufus [II d.C.] em Oribas. 8, 47, 11; escólio sobre Pind., O. 1, 118 v.l.) adv. de <span class=\"greek\">τυπικός</span> (Plut., Mor. 442c), relativo a servir de exemplo ou modelo, como exemplo/advertência, em conexão com a interpretação tipológica da Escritura <span class=\"greek\">ταῦτα</span> <span class=\"greek\">τυπικῶς</span> <span class=\"greek\">συνέβαινεν</span> <span class=\"greek\">ἐκείνοις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:11</a>.—DELG s.v. <span class=\"greek\">τύπτω</span> B. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0364-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τύπος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τύπος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Aeschyl., Hdt.+; inscrições em sentidos variados: New Docs 4, 41f; empréstimo na literatura rabínica).</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> marca produzida em consequência de golpe ou pressão, marca, vestígio (Posidon.: 169 Fgm. 1 Jac.; Anth. Pal. 6, 57, 5 <span class=\"greek\">ὀδόντων</span>; Athen. 13, 49, 585c <span class=\"greek\">τῶν</span> <span class=\"greek\">πληγῶν</span>; Diog. L. 7, 45; 50 a respeito de um anel de sinete; ViJer 13 [p. 73, 10 Sch.]; Philo, Mos. 1, 119; Jos., Bell. 3, 420; PGM 4, 1429; 5, 307.—<span class=\"greek\">ὁ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">αἰσθήσεως</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">διανοίᾳ</span> <span class=\"greek\">γινόμενος</span> Did., Gen. 217, 19) <span class=\"greek\">τῶν</span> <span class=\"greek\">ἥλων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:25ab</a> (v.l. <span class=\"greek\">τὸν</span> <span class=\"greek\">τόπον</span>).—Este talvez seja o lugar para <span class=\"greek\">οἱ</span> <span class=\"greek\">τύποι</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">λίθων</span> Hs 9, 10, 1f (retirar uma pedra do solo deixa um buraco que apresenta os contornos da pedra, mas, com efeito, foi a pedra que produziu a impressão; v. KLake, Apost. Fathers II, 1917; MDibelius, Hdb. Mas v. 4 abaixo).</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> concretização das características ou da função de um modelo, cópia, imagem (cf. Artem. 2, 85 os filhos são <span class=\"greek\">τύπ</span>. de seus pais.—Cf. <span class=\"greek\">ὁ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ἥλιος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τύπῳ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἐστιν</span> Theoph. Ant. 2, 15 [p. 138, 8]) o senhor é um <span class=\"greek\">τύπος</span> <span class=\"greek\">θεοῦ</span>, imagem de Deus para o escravo B 19:7; D 4:11. O supervisor/bispo é <span class=\"greek\">τύπος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρός</span> ITr 3:1; cf. IMg 6:1ab (em ambos os casos aqui, <span class=\"greek\">τύπον</span> é conjectura de Zahn, favorecida por Lghtf., em lugar de <span class=\"greek\">τόπον</span>, que é unanimemente lido pelos mss. gregos e latinos e que pode ser conservado, com Funk, Hilgenfeld, Krüger, Bihlmeyer).</p><p class=\"entry-text\"><span class=\"sense-number\">③</span> objeto formado para se assemelhar a alguma entidade, imagem, estátua de qualquer tipo de material (Hdt. 3, 88,3 <span class=\"greek\">τύπ</span>. <span class=\"greek\">λίθινος</span>. A respeito de imagens dos deuses Herodian 5, 5, 6; Jos., Ant. 1, 311 <span class=\"greek\">τ</span>. <span class=\"greek\">τύπους</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">θεῶν</span>; 15, 329; SibOr 3, 14) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.43\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:43</a> (Am 5:26).</p><p class=\"entry-text\"><span class=\"sense-number\">④</span> espécie, classe ou coisa que sugere um modelo ou padrão, forma, figura, padrão (Aeschyl. et al.; Pla., Rep. 387c; 397c) <span class=\"greek\">ἐποίησεν</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">ἄλλον</span> <span class=\"greek\">τύπον</span> ele nos fez pessoas de outro feitio B 6:11. <span class=\"greek\">τύπος</span> <span class=\"greek\">διδαχῆς</span> padrão de ensinamento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:17</a> (cf. <span class=\"greek\">διδαχή</span> 2; Iambl., Vi. Pyth. 23, 105 <span class=\"greek\">τὸν</span> <span class=\"greek\">τύπον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">διδασκαλίας</span>.—O emprego de <span class=\"greek\">τύπος</span> para os ‘rescritos’ imperiais [p. ex. OGI 521, 5; v. nota 4, especialmente as referências a <span class=\"greek\">θεῖος</span> <span class=\"greek\">τύπος</span>] aparece tarde demais para merecer séria consideração.—JKürzinger, Biblica 39, ’58, 156–76; ELee, NTS 8, ’61/62, 166–73 [‘molde’]). A respeito da forma (de expressão) (Dionys. Hal., Ad Pomp. 4, 2 Rad.; PLips 121, 28 [II d.C.]; POxy 1460, 12) <span class=\"greek\">γράψας</span> <span class=\"greek\">ἐπιστολὴν</span> <span class=\"greek\">ἔχουσαν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τύπον</span> <span class=\"greek\">τοῦτον</span> (cf. EpArist 34 <span class=\"greek\">ἐπιστολὴ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τύπον</span> <span class=\"greek\">ἔχουσα</span> <span class=\"greek\">τοῦτον</span>) aproximadamente como segue, desta maneira, nestes termos (assim numerosas versões) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:25</a>, mas v. a seguir.—Sobre <span class=\"greek\">τοὺς</span> <span class=\"greek\">τύπους</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">λίθων</span> <span class=\"greek\">ἀναπληροῦν</span> Hs 9, 10, 1 v. <span class=\"greek\">ἀναπληρόω</span> 3 e 1 acima.</p><p class=\"entry-text\"><span class=\"sense-number\">⑤</span> conteúdo de um documento, texto, conteúdo (Iambl., Vi. Pyth. 35, 259 <span class=\"greek\">τύπος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">γεγραμμένων</span>; 3 Macc 3:30; PFlor 278 II, 20 [III d.C.] <span class=\"greek\">τῷ</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">τύπῳ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">χρόνῳ</span>=do mesmo conteúdo e data) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:25</a> (EpArist 34 <span class=\"greek\">ἐπιστολὴ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τύπον</span> <span class=\"greek\">ἔχουσα</span> <span class=\"greek\">τοῦτον</span>). Cf. POxy 3366, 28 (a respeito de uma cópia de carta), 32 (o original). V. New Docs 1, 77f (com advertência contra a confusão entre a prática retórica na composição de discursos e a inclusão de cartas cujo valor residia em sua expressão literal). Para uma opinião diferente, v. 4 acima; mais ambivalentemente Hemer, Acts 347f.</p><p class=\"entry-text\"><span class=\"sense-number\">⑥</span> arquétipo que serve de modelo, tipo, padrão, modelo (Pla., Rep. 379a <span class=\"greek\">περὶ</span> <span class=\"greek\">θεολογίας</span>)</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> tecnicamente, projeto, padrão (Diod S 14, 41, 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.44\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:5</a> (cf. sobre ambos Ex 25:40).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> na vida moral, exemplo, padrão (OGI 383, 212 [I a.C.] <span class=\"greek\">τ</span>. <span class=\"greek\">εὐσεβείας</span>; SibOr 1, 380; Did., Gen. 125, 27; em sentido pejorativo 4 Macc 6:19 <span class=\"greek\">ἀσεβείας</span> <span class=\"greek\">τύπ</span>.) <span class=\"greek\">τύπος</span> <span class=\"greek\">γίνου</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πιστῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:12</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:3</a>; IMg 6:2.—V. ESelwyn, 1 Pt ’46, 298f.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓒ</span> a respeito dos tipos dados por Deus como indicação do futuro, sob a forma de pessoas ou coisas (cf. Philo, Op. M. 157; Iren. 1, 6, 4 [Harv. I 74, 3]); a respeito de Adão: <span class=\"greek\">τύπος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μέλλοντος</span> (<span class=\"greek\">Ἀδάμ</span>) tipo do Adão vindouro (isto é, de Cristo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:14</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:6</a>, 11 v.l.; B 7:3, 7, 10f; 8:1; 12:2, 5f, 10; 13:5. <span class=\"greek\">χριστὸς</span> <span class=\"greek\">Ἰησοῦς</span> … <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">τύπον</span> <span class=\"greek\">ἔδειξε</span> Jesus Cristo mostrou-se como o exemplo primordial da ressurreição AcPlCor 2:6 (cf. Just., D. 40, 1 <span class=\"greek\">τύπος</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">χριστοῦ</span>). Também a respeito dos símbolos figurativos que Hermas vê e de seu sentido mais profundo Hv 3, 11, 4. A visão serve <span class=\"greek\">εἰς</span> <span class=\"greek\">τύπον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θλίψεως</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐπερχομένης</span> como símbolo ou prefiguração da tribulação vindoura 4, 1, 1; cf. 4, 2, 5; 4, 3, 6. As duas árvores devem ser <span class=\"greek\">εἰς</span> <span class=\"greek\">τύπον</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">δούλοις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> Hs 2:2a; cf. b.—<span class=\"greek\">ἐν</span> <span class=\"greek\">τύπῳ</span> <span class=\"greek\">χωρίου</span> <span class=\"greek\">Ῥωμαίων</span> IRo ins é conjectura de Zahn em lugar de <span class=\"greek\">ἐν</span> <span class=\"greek\">τόπῳ</span> <span class=\"greek\">χ</span>. <span class=\"greek\">Ῥ</span>., que é lido por todos os mss. e faz bom sentido.—AvBlumenthal, <span class=\"greek\">Τύπος</span> u. <span class=\"greek\">παράδειγμα</span>: Her 63, 1928, 391–414; LGoppelt, Typos. D. typolog. Deutung des AT im Neuen ’39; RBultmann, TLZ 75, ’50, cols. 205–12; AFridrichsen et al., The Root of the Vine (tipologia) ’53; GLampe e KWoollcombe, Essays in Typology, ’57; KOstmeyer, NTS 46, ’00, 112–31.—New Docs 1, 77f; 4, 41. DELG s.v. <span class=\"greek\">τύπτω</span> B. M-M. EDNT. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0364-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τύπτω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τύπτω</span> imperf. <span class=\"greek\">ἔτυπτον</span>; 1 aor. 3 sing. <span class=\"greek\">ἔτυψεν</span> GJs 13:1 (Hom.+.—Defectivo, v. B-D-F §101; Mlt-H. 262) infligir um golpe, golpear, bater, ferir</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> lit. <span class=\"greek\">τινά</span> alguém (Jos., Ant. 20, 206, Vi. 108; 233) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.49\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:49</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:45</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:17</a>; 21:32 (cf. 22:25; PLips 40, 21 <span class=\"greek\">ἐλευθέρους</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">τύπτητε</span> v. Taubenschlag, OpMin II 723); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:11</a> v.l. Pass. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:3b</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">στόμα</span> <span class=\"greek\">τινός</span> golpear alguém na boca 23:2. <span class=\"greek\">τὸ</span> <span class=\"greek\">πρόσωπόν</span> <span class=\"greek\">τινος</span> golpear alguém no rosto (Hermippus Com. [V a.C.] 80) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.64\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:64</a> v.l.; <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κεφαλὴν</span> <span class=\"greek\">καλάμῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:19</a> (quanto ao dat. cf. Diod S 15, 86, 2 <span class=\"greek\">ἀλλήλους</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">δόρασι</span>; Quint. Smyrn. 1, 247). <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σιαγόνα</span> golpear alguém na face <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:29</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κεφαλήν</span> <span class=\"greek\">τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:30</a>. Como sinal de contrição ou tristeza (cf. Arrian, Anab. 7, 24, 3 <span class=\"greek\">τύπτεσθαι</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">στήθη</span>; ApcMos 42; Jos., Ant. 7, 252; Ath. 14, 2) <span class=\"greek\">ἔτυπτεν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">στῆθος</span> <span class=\"greek\">ἑαυτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:13</a>. <span class=\"greek\">τύπτοντες</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">στήθη</span> 23:48. <span class=\"greek\">ἔτυψεν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πρόσωπον</span> <span class=\"greek\">αὐτοῦ</span> GJs 13:1. <span class=\"greek\">τύπτω</span> <span class=\"greek\">κατά</span> <span class=\"greek\">τι</span> bater sobre algo (escólio sobre Nicander, Alexiph. 456): <span class=\"greek\">κατὰ</span> <span class=\"greek\">ἕνα</span> <span class=\"greek\">λίθον</span> <span class=\"greek\">ἔτυπτεν</span> ele batia sobre cada pedra individualmente Hs 9, 6, 3. Pass. a respeito de uma bigorna IPol 3:1.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> fig. golpear, agredir</p><p class=\"entry-text\"><span class=\"greek\">α</span>. infortúnios designados como golpes provenientes de Deus (Ex 7:27; 2 Km 24:17; Ezk 7:6; 2 Macc 3:39; EpArist 192) golpear <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:3a</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. <span class=\"greek\">τύπ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">συνείδησίν</span> <span class=\"greek\">τινος</span> agredir a consciência de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 8:12</a> (Il. 19, 125 ‘uma dor aguda o atingiu até as profundezas do espírito’; Hdt. 3, 64, 1 <span class=\"greek\">Καμβύσεα</span> <span class=\"greek\">ἔτυψε</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀληθείη</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">λόγων</span> ‘a verdade das palavras atingiu Cambises’; 1 Km 1:8).—B. 552f.—DELG. M-M. EDNT. TW. Cf. <span class=\"greek\">πατάσσω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0364-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυραννίς, ίδος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τυραννίς</span>, <span class=\"greek\">ίδος</span>, <span class=\"greek\">ἡ</span> domínio autocrático de um Estado ou de um povo, governo despótico, tirania (assim Archilochus [VII a.C.], Hdt. et al.; LXX, Philo; Jos., Bell. 4, 166, Ant. 1, 114, Vi. 260; SibOr 3, 202; Just., A I, 3, 2; Mel., P. 49, 354 al.; Ath. 30, 1) <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τυραννίδι</span> a fim de estabelecer uma tirania Dg 7:3.—HBerve, Die Tyrannis ’67.—DELG s.v. <span class=\"greek\">τύραννος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0364-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τύραννος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τύραννος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (no sentido geral de ‘governante absoluto’, frequentemente a respeito de divindades, sem conotação negativa, Aeschyl. et al.; inscrições [p. ex. IAndrosIsis, Kyme 3a]; mas também, como indicado abaixo, no sentido negativo empregado em nossa literatura) governante autocrático, déspota, tirano (assim Theognis, Hdt. +; inscrições, papiros, LXX, TestSol; EpArist 289; Philo; Jos., Bell. 5, 439, C. Ap. 2, 241; apologistas exceto Ar.; empréstimo na literatura rabínica) MPol 2:4 v.l.(Mitt-Wilck, I/2, 20 II, 5=POxy 33: Apiano, dissidente político, chama o imperador Cômodo (?) de <span class=\"greek\">τύραννος</span>, embora o imperador, linha 6, deseje ser conhecido como <span class=\"greek\">βασιλεύς</span>). Com <span class=\"greek\">λῃστής</span> e <span class=\"greek\">δυνάστης</span> Ath., R. 19 p. 72, 25). Com <span class=\"greek\">βασιλεύς</span> (Memnon [I a.C./I d.C.]: 434 Fgm. 1, 4, 6 Jac.; Wsd 12:14; Philo; Jos., Ant. 11, 287; 18, 169) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:39</a> D.—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0364-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τύραννος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Τύραννος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (lit.; Joseph. [índice]; inscrições, papiros) Tirano, efésio em cuja sala (v. <span class=\"greek\">σχολή</span>) Paulo proferia discursos. Se esse homem, de resto desconhecido, era ele próprio professor de filosofia ou retórica, ou se simplesmente possuía a casa em que se situava a sala, não sabemos (segundo Diog. L. 9, 54 Protágoras proferia seus discursos em Atenas <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">Εὐριπίδου</span> <span class=\"greek\">οἰκίᾳ</span> ou, segundo outros, <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">Μεγακλείδου</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:9</a>.—Haenchen ad loc.; Hemer, Acts 234.—LGPN I. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0364-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυρβάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τυρβάζω</span> (<span class=\"greek\">τύρβη</span> ‘desordem, confusão’; Ps.-Hes, Soph. et al.) causar agitação, méd. ou pass. em sentido ativo, inquietar-se, estar perturbado, estar agitado <span class=\"greek\">περί</span> <span class=\"greek\">τι</span> com ou acerca de algo (Aristoph., Pax 1007) <span class=\"greek\">περὶ</span> <span class=\"greek\">πολλά</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:41</a> v.l. (Nilus, Ep. 2, 258 <span class=\"greek\">μὴ</span> <span class=\"greek\">ἄγαν</span> <span class=\"greek\">τυρβάζου</span>).—DELG s.v. <span class=\"greek\">τύρβη</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0364-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τύριος, ου, ὁ</h1><div class=\"entry-meta\"><span>gentílico masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Τύριος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hdt. et al.; Joseph. [índice]; inscrições, LXX) o tírio (v. <span class=\"greek\">Τύρος</span>; SibOr 4, 90) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:20</a>, 22 D.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0364-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τύρος, ου, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Τύρος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ἡ</span> (Hdt. et al.; Joseph. [índice], inscrições, LXX; SibOr 5, 455.—Heb. <span class=\"hebrew\">צֹר</span>; aram. <span class=\"hebrew\">טוּר</span>) Tiro, cidade na Fenícia <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:3</a>, 7. Mencionada juntamente com Sidom <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:21f</a>; 15:21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:8</a>; 7:24 (<span class=\"greek\">καί</span> <span class=\"greek\">Σ</span>. v.l.), 31; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:17</a>; 10:13f.—WFleming, The History of Tyre 1915; Kl. Pauly V 1027–29; PECS 944; OEANE V 247–50.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0364-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυφλός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τυφλός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (v. o verbete seguinte; Hom.+) ‘cego’</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> relativo à incapacidade de ver, cego, lit. (frequente nos evangelhos canônicos)</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> adj.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. como atributo <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">τυφλός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:1</a> (v. <span class=\"greek\">γενετή</span>); <span class=\"greek\">τυφ</span>. <span class=\"greek\">προσαίτης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:46</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. como predicativo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:18</a>, 24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:11</a> (cf. cegueira resultante da exposição a uma aparição Hdt. 6, 117; Plut., Mor. 305c; v. Reader, Polemo 239); Dg 2:4 (quase palavra por palavra como Plut., Mor. 420b <span class=\"greek\">εἴδωλα</span> <span class=\"greek\">κωφὰ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τυφλὰ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἄψυχα</span>). Principalmente</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> subst. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:27f</a>; 11:5; 20:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:22f</a> (LSzimonidesz, D. Heilung des Blinden von Bethsaida u. Buddhas Gleichn. von den Blindgeborenen u. dem Elefanten: NThT 24, ’35, 233–59); 10:49, 51; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:21f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:3</a>; 10:21; 11:37 al. (sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:22</a> v. também <span class=\"greek\">κωφός</span> 2). Sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:39</a> v. <span class=\"greek\">ὁδηγέω</span> 1 e cf. Sext. Emp., <span class=\"greek\">Πρὸς</span> <span class=\"greek\">Μαθημ</span>. I, 31 <span class=\"greek\">ὡς</span> <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τυφλὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τυφλὸν</span> <span class=\"greek\">ὁδηγεῖν</span> (subentende-se <span class=\"greek\">δύναται</span>). <span class=\"greek\">τυφλοὺς</span> <span class=\"greek\">θεραπεύων</span> AcPl Ha 8, 36.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> relativo à incapacidade de entender, incapaz de compreender, cego, a respeito da cegueira mental e espiritual em linguagem figurada, extensão fig. do sentido 1 (desde Pind.; Soph., Oed. R. 371; Lucian, Vit. Auct. 18 <span class=\"greek\">τῆς</span> <span class=\"greek\">ψυχῆς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ὀφθαλμόν</span>; Ps 145:8; Philo; Jos., C. Ap. 2, 142 <span class=\"greek\">τυφλὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">νοῦν</span>. <span class=\"greek\">ὀφθαλμοὶ</span> <span class=\"greek\">τυφλῶν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχήν</span> Orig., C. Cels. 2, 48, 38.).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> adj.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. como atributo <span class=\"greek\">ὁδηγὸς</span> <span class=\"greek\">τυφλός</span> (cf. X., Mem. 1, 3, 4; Demetr. Phaler. [IV a.C.; ed. FWehrli ’49], Fgm. 121 <span class=\"greek\">οὐ</span> <span class=\"greek\">μόνον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πλοῦτον</span> <span class=\"greek\">τυφλόν</span>, <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδηγοῦσαν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">τύχην</span>; Philo, Virt. 7; Just., D. 134, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:14</a>; 23:16, 24. <span class=\"greek\">Φαρισαῖε</span> <span class=\"greek\">τυφλέ</span> v. 26.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. como predicativo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.40\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:40f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:17</a>. <span class=\"greek\">τυφλοί</span> <span class=\"greek\">εἰσιν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">καρδίᾳ</span> <span class=\"greek\">αὐτῶν</span> Ox 1 verso, 20f=GTh 28.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> subst. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:17</a>, 19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:19</a> aqui metaforicamente a respeito daqueles que não se converteram ao modo de vida mosaico; B 14:7 (Is 42:7), 9 (Is 61:1), <span class=\"greek\">οὐαὶ</span> <span class=\"greek\">τυφλοὶ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ὁρῶντες</span> Ox 840, 31.—SRoth, The Blind, the Lame, and the Poor ’97 (Lucas-Atos).—B. 322. DELG s.v. <span class=\"greek\">τύφομαι</span> B. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0364-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυφλόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τυφλόω</span> (<span class=\"greek\">τυφλός</span>) 1 aor. <span class=\"greek\">ἐτύφλωσα</span>; perf. <span class=\"greek\">τετύφλωκα</span>; aor. pass. 3 sing. <span class=\"greek\">ἐτυφλώθη</span>,-<span class=\"greek\">θησαν</span> LXX (Pind., Hdt. et al.; CB I/2, 386 n.º 232, 15; PLond V, 1708, 84; LXX; TestSol 12:2 P; Test12Patr) privar da visão, cegar, em nossa literatura somente em linguagem figurada (Is 42:19) <span class=\"greek\">τετύφλωκεν</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ὀφθαλμούς</span> (cf. TestDan 2:4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.40\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:40</a> (cf. Is 6:10).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:11</a>; ou fig. <span class=\"greek\">τυφ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">νοήματα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:4</a> (Pla., Phd. 99e <span class=\"greek\">μὴ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχὴν</span> <span class=\"greek\">τυφλωθείην</span>; Herm. Wr. 478, 32 Sc.; Philo, Ebr. 108 <span class=\"greek\">διάνοιαν</span> <span class=\"greek\">τυφλωθείς</span>; Jos., Ant. 8, 30; Test Sim 2:7 <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄρχων</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πλάνης</span> <span class=\"greek\">ἐτύφλωσέ</span> <span class=\"greek\">μου</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">νοῦν</span>).—DELG s.v. <span class=\"greek\">τύφομαι</span> B. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0364-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τῦφος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τῦφος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> (de <span class=\"greek\">τύφω</span>, primariamente ‘produzir fumaça’) em lugar do habitual (cf. <span class=\"greek\">ζῆλος</span>, início) <span class=\"greek\">τῦφος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> convicção que não está arraigada na realidade, ilusão, presunção, arrogância (assim Pla. et al.; Philo Bybl. [c. 100 d.C.]: 790 Fgm. 1 p. 805, 7 Jac. [em Eus., PE 1, 9, 26]; Dio Chrys. 4, 6; Vett. Val. 4, 28; 150, 5; 3 Macc 3:18; SibOr 8, 8; 111; Philo; Jos., Ant. 9, 922; Tat. 1, 2) a respeito daqueles que têm noções exageradas da própria importância 1 Cl 13:1.—DELG s.v. <span class=\"greek\">τύφομαι</span>. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0364-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυφόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τυφόω</span> (<span class=\"greek\">τῦφος</span>) 1 aor. pass. <span class=\"greek\">ἐτυφώθην</span>; perf. pass. <span class=\"greek\">τετύφωμαι</span>; ‘obscurecer, iludir’, mas somente em sentido fig. e bastante predominantemente, em nossa literatura exclusivamente, na pass. (Hippocr., Pla.) <span class=\"greek\">τυφόομαὶ</span> para nossa literatura os sentidos são certamente</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> ensoberbecer-se, ser presunçoso (Strabo 15, 1, 5; Plut., Mor. 59a; Aelian, VH 3, 28; Diog. L. 6, 7; 26 al.; Philo, Congr. Erud. Gr. 128; Jos., Vi. 53) <span class=\"greek\">τυφωθείς</span> (cf. Sext. Emp., Pyrrh. 3, 193) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:6</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:4</a>. As versões antigas também entendem <span class=\"greek\">τετύφωται</span> <span class=\"greek\">μηδὲν</span> <span class=\"greek\">ἐπιστάμενος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:4</a> neste sentido, embora esta passagem possa pertencer ao sentido 2 ou 3.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> ser cegado, tornar-se insensato (Hippocr. et al.) perf. pass. em sentido ativo, ser insensato, estúpido (Demosth. 9, 20; 19, 219 <span class=\"greek\">μαίνομαι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τετύφωμαι</span>; Polyb. 3, 81, 1 <span class=\"greek\">ἀγνοεῖ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τετύφωται</span>; Dio Chrys. 30 [47], 18 <span class=\"greek\">ἢ</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">τετύφωμαι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀνόητός</span> <span class=\"greek\">εἰμι</span>; Philo, Conf. Lingu. 106; Jos., C. Ap. 1, 15; 2, 255) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:4</a> (v. 1).—DELG s.v. <span class=\"greek\">τύφομαι</span>. M-M. Spicq.</p><p class=\"entry-text\"><span class=\"sense-number\">③</span> estar mentalmente enfermo (cf. Demosth. 9, 20; Plut., Mor. 81f). AMalherbe (Medical Imagery in the Pastoral Letters: Paul and the Popular Philosophers ’89, 123f, especialmente n. 7) considera este sentido “bastante provável” para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:4</a>. Cf. VLeinieks, The City of Dionysos ’96, 107–22.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0364-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τύφω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τύφω</span> (Eur., Hdt. et al.) emitir fumaça, pass. fumegar, arder lentamente sem chama, bruxulear (Philostrat., Vi. Apoll. 5, 17 p. 177, 30; Jos., Bell. 6, 257) a respeito de um pavio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:20</a> (v. a literatura s.v. <span class=\"greek\">κάλαμος</span> 1).—DELG s.v. <span class=\"greek\">τύφομαι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0364-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυφωνικός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τυφωνικός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> semelhante a um turbilhão <span class=\"greek\">ἄνεμος</span> <span class=\"greek\">τυφωνικός</span> um tufão, furacão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:14</a> (Etym. Mag. p. 755, 11 <span class=\"greek\">τῶν</span> <span class=\"greek\">τυφωνικῶν</span> <span class=\"greek\">καλουμένων</span> <span class=\"greek\">πνευμάτων</span>; escólio sobre Soph., Ant. 418 p. 239 P. <span class=\"greek\">τὸν</span> <span class=\"greek\">τυφώνιον</span> <span class=\"greek\">ἄνεμον</span>; Eustath. em Il. 2, 782 p. 345, 43).—Rdm.2 28f.—Frisk s.v. <span class=\"greek\">τύφομαι</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0364-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυχεῖν, τύχοι</h1><div class=\"entry-meta\"><span>formas verbais</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τυχεῖν</span>, <span class=\"greek\">τύχοι</span> v. <span class=\"greek\">τυγχάνω</span>.</p></section></article>"};
